/* StudentPath interface. No policy claims or authenticated uploads are simulated. */
const $ = (selector) => document.querySelector(selector);
const state = { gateway: '', busy: false, policies: [], controller: null, turn: 0 };
const icons = (name) => { if (name === 'harp') { const img = document.createElement('img'); img.src = 'coat-of-arms-of-ireland.svg'; img.alt = 'Coat of arms of Ireland'; img.width = 19; img.height = 24; return img; } const svg = document.createElementNS('http://www.w3.org/2000/svg','svg'); const use = document.createElementNS(svg.namespaceURI,'use'); use.setAttribute('href',`#${name}`); svg.append(use); return svg; };
const text = (tag, value, cls) => { const el=document.createElement(tag); el.textContent=value; if(cls)el.className=cls; return el; };
function toast(message) { const el=$('#toast'); el.textContent=message; el.hidden=false; clearTimeout(toast.timer); toast.timer=setTimeout(()=>el.hidden=true,4000); }
function setView(view){ $('#welcome').hidden=view!=='welcome'; $('#conversation').hidden=view!=='chat'; $('#admin-view').hidden=view!=='admin'; const links=$('#underbar'); links.hidden=view==='admin'; (view==='chat'?$('#conversation'):$('.welcome-inner')).append(links); }
function resetChat(){ state.turn++; if(state.controller)state.controller.abort(); state.busy=false; document.querySelectorAll('.send-button').forEach(b=>b.disabled=false); $('#messages').replaceChildren(); $('#welcome-input').value=''; $('#chat-input').value=''; setView('welcome'); $('#welcome-input').focus(); }
document.querySelectorAll('[data-new],.brand').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();resetChat();}));
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('#admin-button').addEventListener('click',()=>$('#admin-dialog').showModal());
$('#about-button').addEventListener('click',()=>$('#about-dialog').showModal());
$('#connection-button').addEventListener('click',()=>{$('#gateway-url').value=state.gateway;$('#connection-dialog').showModal();});
$('#preview-admin').addEventListener('click',()=>{$('#admin-dialog').close();setView('admin');$('#admin-title').setAttribute('tabindex','-1');$('#admin-title').focus();});
$('#leave-admin').addEventListener('click',()=>setView($('#messages').children.length?'chat':'welcome'));
$('#connection-form').addEventListener('submit',e=>{e.preventDefault(); const value=$('#gateway-url').value.trim();try{if(value){const url=new URL(value);if(!['https:','http:'].includes(url.protocol)||url.username||url.password||url.search||url.hash)throw Error();state.gateway=url.href.replace(/\/$/,'');}else state.gateway='';$('#connection-error').textContent='';$('#mode-label').textContent=state.gateway?'Gateway configured':'Interface preview';$('#connection-dialog').close();toast(state.gateway?'Gateway saved. Availability will be checked when you ask a question.':'Interface preview enabled.');}catch{$('#connection-error').textContent='Enter an HTTP or HTTPS address without credentials, query parameters or fragments.';}});
function addMessage(role,content){const message=text('article','','message '+role);if(role==='assistant'){const label=text('div','','message-label');label.append(icons('harp'),document.createTextNode('StudentPath'));message.append(label);}message.append(text('p',content));$('#messages').append(message);message.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});return message;}
function safeLink(raw){try{const url=new URL(raw);return ['http:','https:'].includes(url.protocol)?url.href:null;}catch{return null;}}
function renderAnswer(el,data){if(!['answered','degraded','insufficient_evidence'].includes(data.status)||!Array.isArray(data.sources))throw Error('The gateway returned an unsupported response.');el.querySelector('p').textContent=data.answer||(data.status==='insufficient_evidence'?'There is not enough retrieved evidence to answer this question. Try a more specific question or consult the official guidance.':'An answer could not be generated. Review the retrieved evidence below.');if(Array.isArray(data.checklist)&&data.checklist.length){const list=document.createElement('ul');data.checklist.filter(x=>typeof x==='string').forEach(x=>list.append(text('li',x)));el.append(list);}if(data.stub===true)el.append(text('p','Gateway stub response: this is placeholder content, not official guidance.','evidence-label'));if(data.sources.length){el.append(text('p','RETRIEVED SOURCES','evidence-label'));data.sources.forEach((source,i)=>{const href=safeLink(source.url);const item=text(href?'a':'div',`${i+1}. ${source.source_id||'Source'} · ${source.passage||source.text||source.url||''}`,'source-link');if(href){item.href=href;item.target='_blank';item.rel='noopener noreferrer';}el.append(item);});}el.append(text('small',`Index: ${data.index_version||'not supplied'} · Collection timestamp: ${data.last_success_at||'not supplied'}`));}
async function ask(question){question=question.trim();if(question.length<3){toast('Please enter a question of at least 3 characters.');return;}if(question.length>500||state.busy)return;state.busy=true;const turn=++state.turn;setView('chat');addMessage('user',question);const reply=addMessage('assistant',state.gateway?'Looking for relevant evidence…':'');document.querySelectorAll('.send-button').forEach(b=>b.disabled=true);try{if(!state.gateway){reply.querySelector('p').textContent='You’re exploring the StudentPath interface. The REST gateway is not connected, so I can’t retrieve policy evidence or provide a grounded answer yet.';reply.append(text('p','Connect your gateway using connection settings to ask questions against your collection.','muted'));const a=text('a','Browse official Irish immigration guidance ↗','source-link');a.href='https://www.irishimmigration.ie/';a.target='_blank';a.rel='noopener noreferrer';reply.append(a);}else{state.controller=new AbortController();const timer=setTimeout(()=>state.controller?.abort(),35000);let response;try{response=await fetch(state.gateway+'/v1/questions',{method:'POST',headers:{'Content-Type':'application/json','X-Request-ID':crypto.randomUUID()},body:JSON.stringify({question}),signal:state.controller.signal});}finally{clearTimeout(timer);}if(!response.ok)throw Error(`The gateway could not complete this request (HTTP ${response.status}).`);const data=await response.json();if(turn!==state.turn)return;renderAnswer(reply,data);}}catch(error){if(turn!==state.turn)return;reply.querySelector('p').textContent=error.name==='AbortError'?'This request took too long. Please try again.':error.message==='Failed to fetch'?'The gateway could not be reached. Check its address, availability and CORS configuration.':error.message;reply.append(text('small','No policy answer has been generated.'));}finally{if(turn===state.turn){state.busy=false;state.controller=null;document.querySelectorAll('.send-button').forEach(b=>b.disabled=false);$('#chat-input').focus();}}}
[['#welcome-form','#welcome-input'],['#chat-form','#chat-input']].forEach(([form,input])=>{$(form).addEventListener('submit',e=>{e.preventDefault();const q=$(input).value;if(q.trim().length>=3){$(input).value='';ask(q);}else toast('Please enter a question of at least 3 characters.');});$(input).addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$(form).requestSubmit();}});});
document.querySelectorAll('.topic').forEach(b=>b.addEventListener('click',()=>ask(b.dataset.question)));
function fileValid(file){return file&&/\.(pdf|txt|html)$/i.test(file.name)&&file.size>0&&file.size<=10*1024*1024;}
function showFile(){const file=$('#policy-file').files[0];$('#file-label').textContent=file?file.name:'Choose a document';$('#upload-error').textContent=file&&!fileValid(file)?'Choose a non-empty PDF, TXT or HTML file up to 10 MB.':'';}
$('#policy-file').addEventListener('change',showFile);
['dragover','dragenter'].forEach(name=>$('#drop-zone').addEventListener(name,e=>{e.preventDefault();$('#drop-zone').classList.add('dragging');}));['dragleave','drop'].forEach(name=>$('#drop-zone').addEventListener(name,e=>{e.preventDefault();$('#drop-zone').classList.remove('dragging');if(name==='drop'&&e.dataTransfer.files.length){const transfer=new DataTransfer();transfer.items.add(e.dataTransfer.files[0]);$('#policy-file').files=transfer.files;showFile();}}));
function renderPolicies(){const list=$('#policy-list');list.replaceChildren();$('#policy-count').textContent=`${state.policies.length} document${state.policies.length===1?'':'s'}`;if(!state.policies.length){const box=text('div','','empty-queue');box.append(icons('book'),text('h3','A clean slate.'),text('p','Documents you stage will appear here. Nothing is published automatically.'));list.append(box);}state.policies.forEach(p=>{const item=text('article','','policy-item');item.append(text('span','DRAFT · THIS TAB ONLY','draft-badge'),text('h3',p.title),text('small',`${p.filename} · ${(p.size/1024).toFixed(0)} KB`),text('small',p.url),text('small',p.date?`Effective: ${p.date}`:'Effective date not supplied'));const remove=text('button','Remove draft','remove-policy');remove.type='button';remove.addEventListener('click',()=>{state.policies=state.policies.filter(x=>x.id!==p.id);renderPolicies();});item.append(remove);list.append(item);});}
$('#upload-form').addEventListener('submit',e=>{e.preventDefault();const file=$('#policy-file').files[0];const title=$('#policy-title').value.trim();if(!fileValid(file)||!title){$('#upload-error').textContent='Add a title and a non-empty PDF, TXT or HTML document up to 10 MB.';return;}const url=new URL($('#policy-url').value);if(url.protocol!=='https:'||!(url.hostname==='irishimmigration.ie'||url.hostname.endsWith('.irishimmigration.ie'))||url.username||url.password){$('#upload-error').textContent='Use an HTTPS source URL on irishimmigration.ie for this collection.';return;}state.policies.unshift({id:crypto.randomUUID(),title,filename:file.name,size:file.size,url:url.href,date:$('#policy-date').value,file});renderPolicies();$('#upload-form').reset();showFile();toast('Draft staged in this tab. It has not been uploaded or indexed.');});

document.querySelectorAll('[data-open-admin]').forEach(button=>button.addEventListener('click',()=>$('#admin-dialog').showModal()));
document.querySelectorAll('[data-open-connection]').forEach(button=>button.addEventListener('click',()=>$('#connection-button').click()));
